CREATE OR REPLACE VIEW public.public_units AS SELECT u.id,u.building_number,u.unit_number,u.unit_type,u.area_m2 AS area,u.activity,a.code AS activity_code,u.price,CASE u.leasing_status WHEN 'available' THEN 'available' WHEN 'leased' THEN 'rented' WHEN 'maintenance' THEN 'maintenance' ELSE 'reserved' END::text AS status,u.leasing_status::text AS leasing_status FROM public.units u JOIN public.buildings b ON b.id=u.building_id LEFT JOIN public.activities a ON a.id=u.activity_id WHERE u.publish_state='published' AND NOT u.is_test AND b.is_published;
GRANT SELECT ON public.public_units TO anon,authenticated,service_role;
DO $$ DECLARE cols text;BEGIN SELECT string_agg(CASE WHEN column_name='status' THEN 'CASE u.leasing_status WHEN ''available'' THEN ''available'' WHEN ''leased'' THEN ''rented'' WHEN ''maintenance'' THEN ''maintenance'' ELSE ''reserved'' END::text AS status' ELSE 'u.'||quote_ident(column_name) END,',' ORDER BY ordinal_position) INTO cols FROM information_schema.columns WHERE table_schema='public' AND table_name='units';EXECUTE 'CREATE OR REPLACE VIEW public.units_status_read WITH (security_invoker=true) AS SELECT '||cols||' FROM public.units u';END $$;
GRANT SELECT ON public.units_status_read TO authenticated,service_role;
REVOKE INSERT,UPDATE,DELETE ON public.units_status_read FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.extend_booking_expiry(_booking_id uuid,_hours integer) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'التمديد يتطلب سببًا؛ استخدم إجراء تمديد الحجز المعتمد';END $$;
CREATE OR REPLACE FUNCTION public.control_set_maintenance(_unit_id uuid,_on boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'السبب مطلوب؛ استخدم إجراء تغيير حالة الوحدة المعتمد';END $$;
CREATE OR REPLACE FUNCTION public.archive_tenant(_unit_id uuid,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'إنهاء الإشغال يتطلب إنهاء العقد المسجل أولًا';END $$;
CREATE OR REPLACE FUNCTION public.create_booking(_customer_full_name text,_customer_phone text,_customer_email text,_business_name text,_notes text,_unit_ids uuid[],_cr_number text DEFAULT NULL::text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.create_booking(_customer_full_name,_customer_phone,_customer_email,_business_name,_notes,_unit_ids,_cr_number,'full',CASE left(btrim(coalesce(_cr_number,'')),1) WHEN '7' THEN 'commercial_registration' WHEN '1' THEN 'national_id' WHEN '2' THEN 'iqama' END);END $$;
CREATE OR REPLACE FUNCTION public.create_booking(_customer_full_name text,_customer_phone text,_customer_email text,_business_name text,_notes text,_unit_ids uuid[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'حدّث نموذج الحجز وحدد نوع الهوية ورقمها';END $$;
CREATE OR REPLACE FUNCTION public.remove_booking_units(_booking_id uuid,_booking_unit_ids uuid[],_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings;link public.booking_units;r text;n integer:=0;remaining integer;BEGIN PERFORM public._assert_admin_writer();r:=public._assert_reason(_reason);SELECT * INTO b FROM public.bookings WHERE id=_booking_id FOR UPDATE;IF NOT FOUND OR b.status NOT IN ('pending','confirmed') THEN RAISE EXCEPTION 'الحجز غير قابل للتعديل'; END IF;FOR link IN SELECT * FROM public.booking_units WHERE booking_id=b.id AND id=ANY(_booking_unit_ids) AND archived_at IS NULL ORDER BY unit_id FOR UPDATE LOOP UPDATE public.booking_units SET archived_at=now(),archived_by=auth.uid(),archive_reason=r WHERE id=link.id;PERFORM public.set_unit_status(link.unit_id,'available',r,'booking_unit_cancel',b.id);PERFORM public._safety_audit('ARCHIVE','booking_units',link.id::text,to_jsonb(link),(SELECT to_jsonb(x) FROM public.booking_units x WHERE id=link.id),r);n:=n+1;END LOOP;IF n=0 THEN RAISE EXCEPTION 'لا توجد وحدات مختارة داخل الحجز';END IF;SELECT count(*) INTO remaining FROM public.booking_units WHERE booking_id=b.id AND archived_at IS NULL;UPDATE public.bookings SET units_count=remaining,total_area=(SELECT coalesce(sum(area),0) FROM public.booking_units WHERE booking_id=b.id AND archived_at IS NULL),total_price=(SELECT coalesce(sum(price),0) FROM public.booking_units WHERE booking_id=b.id AND archived_at IS NULL),status=CASE WHEN remaining=0 THEN 'cancelled' ELSE status END,updated_at=now() WHERE id=b.id;RETURN jsonb_build_object('removed',n,'remaining',remaining);END $$;
SELECT count(*) FROM public.public_units;
SELECT has_column_privilege('anon','public.units','status','UPDATE') AS must_be_false;